"use strict";const utils=require("../utils");module.exports=function(defaultFuncs,api,ctx){return function refreshFb_dtsg(payload,callback){let opts=payload;let cb=callback;if(typeof payload==="function"){cb=payload;opts={}}if(!opts)opts={};if(utils.getType(opts)!=="Object"){throw new Error("The first parameter must be an object or a callback function")}let resolveFunc,rejectFunc;const promise=new Promise((resolve,reject)=>{resolveFunc=resolve;rejectFunc=reject});if(!cb){cb=(err,data)=>{if(err)return rejectFunc(err);resolveFunc(data)}}if(Object.keys(opts).length===0){defaultFuncs.get("https://www.facebook.com/",ctx.jar,{noRef:true}).then(res=>{const html=typeof res==="string"?res:res&&res.body?res.body:res&&res.data?res.data:"";const fb_dtsg=utils.getFrom(html,'["DTSGInitData",[],{"token":"','","')||utils.getFrom(html,'"fb_dtsg":{"token":"','"')||utils.getFrom(html,'name="fb_dtsg" value="','"');const jazoest=utils.getFrom(html,"jazoest=",'"')||utils.getFrom(html,'"jazoest":"','"');if(!fb_dtsg)throw new Error("Could not find fb_dtsg in HTML. Session may have expired.");const ttstamp="2"+Array.from(fb_dtsg).map(c=>c.charCodeAt(0)).join("");const updated={fb_dtsg:fb_dtsg,ttstamp:ttstamp};if(jazoest)updated.jazoest=jazoest;Object.assign(ctx,updated);const result={data:updated,message:"Refreshed fb_dtsg"+(jazoest?" and jazoest":"")};cb(null,result)}).catch(err=>{utils.error("refreshFb_dtsg",err.message||err);cb(err instanceof Error?err:new Error(String(err.message||err)))})}else{const allowed=["fb_dtsg","jazoest","lsd","clientID","userID"];const filtered={};for(const key of allowed){if(key in opts)filtered[key]=opts[key]}Object.assign(ctx,filtered);cb(null,{data:filtered,message:`Updated: ${Object.keys(filtered).join(", ")}`})}return promise}};
